function [nRa17,nRi17,nRi210,min_nRi210,hue_min_nRi210,cct,duv]=CRI2012(spd)
%calculate CRI2012 as published in LRT 2013
%input:
%spd = spectral power distribution of white light source 
%output:
%nRa17: Ra2012 calculated using HL17 
%nRi17: Ri2012 calculated using HL17
%nRi210: Ri2012 calculated using "real 210" set 
%min_nRi210: min Ri2012 value for Real 210 set
%hue_min_nRi210: hue at which min_nRi210 occurs
%cct: correlated colour temperature of test light
%duv: duv of test light

%HL17
[nRa17,nRi17]=CRI2012_sub(spd,1/55,[0,360],17);

%Real210
[dummy,nRi210,DERMS210,DEi210,aMc210,bMc210,dummy2,dummy3,cct,duv]=CRI2012_sub(spd,2/45,[0,360],210);
min_nRi210=min(nRi210);aMc_min=aMc210(nRi210==min_nRi210);bMc_min=bMc210(nRi210==min_nRi210);
hue_min_nRi210=HueAngle(aMc_min,bMc_min);

end

function [nRa,nRi,DERMS,DEi,aMc,bMc,Jc,XYZ,cct,duv]=CRI2012_sub(SPD,cfactor,thetas,sampleset,CCTtype,DD, ref)
%calculate CRI2012 as published in LRT 2013
cfact=1/55;
dl=abs(SPD(1,1)-SPD(2,1));
if nargin==1;thetas=[0,360];sampleset=17;CCTtype=-1;DD=1;cfactor=cfact;end%all hues,sampleset =HL17m,keep equal CCT ref as in CRI1995, Did=1!
if nargin==2;thetas=[0,360];sampleset=17;CCTtype=-1;DD=1;end%sampleset =HL17m,keep equal CCT ref as in CRI1995, Did=1!
if nargin==3;sampleset=17;CCTtype=-1;DD=1;end%keep equal CCT ref as in CRI1995, Did=1!
if nargin==4;CCTtype=-1;DD=1;end%Did=1!
if nargin==5;DD=1;end%Did=1!

