282393970915446	0.282346682899240	0.282299531983229	0.282252517819631	0.282205640060886	0.282158898359660	0.282112292368858	0.282065821741626	0.282019486131359	0.281973285191710	0.281927218576592	0.281881285940190	0.281835486936964	0.281789821221654	0.281744288449293	0.281698888275205	0.281653620355017	0.281608484344663	0.281563479900390	0.281518606678765	0.281473864336678	0.281429252531354	0.281384770920353	0.281340419161576	0.281296196913276	0.281252103834058	0.281208139582886	0.281164303819090	0.281120596202371	0.281077016392805	0.281033564050849	0.280990238837348	0.280947040413536	0.280903968441047	0.280861022581912	0.280818202498574	0.280775507853884	0.280732938311111	0.280690493533944	0.280648173186500	0.280605976933325	0.280563904439402	0.280521955370151	0.280480129391439	0.280438426169582	0.280396845371347	0.280355386663961	0.280314049715112	0.280272834192953	0.280231739766108	0.280190766103676	0.280149912875234	0.280109179750841	0.280068566401043	0.280028072496875	0.279987697709868	0.279947441712049	0.279907304175947	0.279867284774597	0.279827383181543	0.279787599070841	0.279747932117061	0.279708381995297	0.279668948381162	0.279629630950796	0.279590429380869	0.279551343348585	0.279512372531681	0.279473516608437	0.279434775257672	0.279396148158753	0.279357634991592	0.279319235436657	0.279280949174966	0.279242775888098	0.279204715258189	0.279166766967939	0.279128930700614	0.279091206140048	0.279053592970645	0.279016090877384	0.278978699545820	0.278941418662086	0.278904247912896	0.278867186985548	0.278830235567926	0.278793393348501	0.278756660016337	0.278720035261088	0.278683518773007	0.278647110242940	0.278610809362336	0.278574615823241	0.278538529318311	0.278502549540801	0.278466676184579	0.278430908944119	0.278395247514507	0.278359691591443	0.278324240871244	0.278288895050839	0.278253653827780	0.278218516900238	0.278183483967005	0.278148554727498]';
if nargin==1;obs=2;end;if obs==10;ColourTemp=ColourTemp10;end

if size(XYZWT,2)==2;XYZWT=spd2xyz(obs,XYZWT);end

ut=4*XYZWT(1)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));
vt=6*XYZWT(2)/(XYZWT(1)+15*XYZWT(2)+3*XYZWT(3));
dc=((ut-ColourTemp(:,2)).^2+(vt-ColourTemp(:,3)).^2).^0.5;
if ~isnan(min(dc))
eps=1e-8;q=find((dc>=min(dc)-eps) &(dc<=min(dc)+eps));q=q(1);vr=ColourTemp(q,3);
Tm=ColourTemp(q,1);
dm=dc(q);
if Tm~=ColourTemp(end,1) ;
    T1=ColourTemp(q+1,1);
    d1=dc(q+1);
    u1=ColourTemp(q+1,2);
    v1=ColourTemp(q+1,3);
else
    T1=ColourTemp(q,1);
    d1=dc(q);
    u1=ColourTemp(q,2);
    v1=ColourTemp(q,3);
end
if Tm~=ColourTemp(1,1) ;
    T0=ColourTemp(q-1,1);
    d0=dc(q-1);
    u0=ColourTemp(q-1,2);
    v0=ColourTemp(q-1,3);
else
    T0=ColourTemp(q,1);
    d0=dc(q);
    u0=ColourTemp(q,2);
    v0=ColourTemp(q,3);
end
    a=d0/(T0-Tm)/(T0-T1);
    b=dm/(Tm-T0)/(Tm-T1);
    c=d1/(T1-T0)/(T1-Tm);
    A=a+b+c;
    B=-(a*(T1+Tm)+b*(T0+T1)+c*(Tm+T0));
    C=a*Tm*T1+b*T0*T1+c*T0*Tm;
    Tp=-B/(2*A);
    duv=sign(vt-vr).*(A*Tp^2+B*Tp+C);
p=((u1-u0)^2+(v1-v0)^2)^0.5;
p1=(d0^2+p^2-d1^2)/(2*p);
Pt=T0+p1*(T1-T0)/p;
p3=(d0^2-p1^2)^0.5;
p4=Pt;
Ls=p4+(Tp-p4)*p3*100;
if p3<0.001
    CCT=Ls;
else CCT=Tp;
end
else
    CCT=NaN;duv=NaN;
end
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%  ciecam02 ,  matrix form
%  input:  
%   XYZ, 3 by n matrix
%   XYZW, 3 by 1 vector, the trisstimulus values of the light source
%  Did  =  1,   D=1
%          otherwise,  D is computed using formula
% output
% J, C, H, M,s,Q,h : all are 1 by n 
% Hc: Hue composition
%      Hc.percentage, gives the percentage (integers) of Red, Geen, Yellow or Blue
%      Hc.Colour, gives the corresponding colours
%      30B 70G
%      Hc.percentage, gives 30   70
%      Hc.Colour,    B   G
%   InfSucFail: 1 by n vectors
%               1    means sucessfully predicted the pereptual attributes
%               0    fails to predict the perceptual attributes
function [J,C,H,M,s,Q,h,Hc,D,A,td,InfSucFail]=CIECAM02ForwardM(XYZ,XYZW,Yb,Did,F,Nc,c,LA)
% % setup the CAT02 matrix
% MCAT02=[ 0.7328, 0.4296, -0.1624;
%         -0.7036, 1.6975, 0.0061;
%         0.0030,  0.0136, 0.9834];
% %  set up the inverse of MCAT02
% INVMCAT02=[ 1.096124    -0.278869    0.182745;
%             0.454369     0.473533    0.072098;
%            -0.009628    -0.005698    1.015326];
       
%use adjusted CAT02 (3rd line)to solve yellow-blue gamut problem      
MCAT02=[ 0.7328, 0.4296, -0.1624;        -0.7036, 1.6975, 0.0061;        0,  0, 1];
INVMCAT02=  inv(MCAT02);

%setup the HPE matrix
MHPE=[ 0.38971,  0.68898,  -0.07868;
      -0.22981,  1.18340,   0.04641;
      0.00000,  0.0000,     1.00000];
  
%  step 1
RGBW=MCAT02*XYZW';
RGB=MCAT02*XYZ';

% step 2
if Did==1
    D=1;
else
    if Did <=1;D=abs(Did);else;D=F*(1-exp(-(LA+42)/92)/3.6);end
    
end
temp=ones(3,1);
DRGB=inv( diag(RGBW) )*temp*(D*XYZW(2))  +  (1-D)*temp  ;

%Step 3
RGBC=diag(DRGB)*RGB;
RGBWC=diag(DRGB)*RGBW;

% step 4
k=1/(5*LA+1);
FL=0.2*(k^4)*(5*LA) + 0.1*( (1-k^4)^2 )*(5*LA)^(1/3);
n=Yb/XYZW(2);
z=1.48+n^0.5;
Nbb=0.725*(1/n)^0.2;
Ncb=Nbb;

%Step 5
RGB1=MHPE*INVMCAT02*RGBC;
RGBW1=MHPE*INVMCAT02*RGBWC;

%solve purple problem! with CAT02 based CAT transform
RGB1=MHPE*INVMCAT02*RGBC;RGB1(RGB1<0)=0;
RGBW1=MHPE*INVMCAT02*RGBWC;RGBW1(RGBW1<0)=0;

%step 6
RGBA1=CAM02RGBA1M(RGB1,FL);
RGBAW1=CAM02RGBA1M(RGBW1,FL);

%step 7, a and b are row vectors
a=RGBA1(1,:)-12*RGBA1(2,:)/11+RGBA1(3,:)/11;
b=(RGBA1(1,:)+RGBA1(2,:)-2*RGBA1(3,:))/9;

%  h is a row vector 
h=HueAngle(a,b);

% step 8
ColourName=[' Red  ';'Yellow';'Green ';' Blue ';' Red  '];
HueTable=[1       2        3       4       5;
          20.14   90.0    164.25  237.53   380.14;
          0.8    0.7      1.0      1.2      0.8;
          0.     100.0    200.0   300.0    400.0];
%
s1=h<20.14;
s2=h>=20.14;
h1=s1.*(h+360)+s2.*h;
%
s1=h1<HueTable(2,2);
s2=(h1>=HueTable(2,2))&(h1<HueTable(2,3));
s3=(h1>=HueTable(2,3))&(h1<HueTable(2,4));
s4=(h1>=HueTable(2,4))&(h1<=HueTable(2,5));
%
et=0.25*( cos(h1*pi/180+2) +3.8 );
e=et*(50000/13)*Nc*Ncb;
%
i=1;
H1=HueTable(4,i)+100*( (h1-HueTable(2,i))/HueTable(3,i) )./( (h1-HueTable(2,i))/HueTable(3,i) + (HueTable(2,i+1)-h1)/HueTable(3,i+1) );
i=2;
H2=HueTable(4,i)+100*( (h1-HueTable(2,i))/HueTable(3,i) )./( (h1-HueTable(2,i))/HueTable(3,i) + (HueTable(2,i+1)-h1)/HueTable(3,i+1) );
i=3;
H3=HueTable(4,i)+100*( (h1-HueTable(2,i))/HueTable(3,i) )./( (h1-HueTable(2,i))/HueTable(3,i) + (HueTable(2,i+1)-h1)/HueTable(3,i+1) );
i=4;
H4=HueTable(4,i)+100*( (h1-HueTable(2,i))/HueTable(3,i) )./( (h1-HueTable(2,i))/HueTable(3,i) + (HueTable(2,i+1)-h1)/HueTable(3,i+1) );
H=s1.*H1+s2.*H2+s3.*H3+s4.*H4;
%
kk=floor(H/100);
Hp=round( 100*((H/100)-kk ) );
i=kk+1;
%Hc = struct( 'percentage',{Hp 100-Hp},'Colour',{ColourName(i+1,1:6), ColourName(i,1:6) } );
Hc={'disabled'};

% Step 9
ca=[2 1 1/20];
aaa=sum(ca)*0.1;
A=Nbb*( ca*RGBA1- aaa );
AW=Nbb*( ca*RGBAW1 - aaa );

% step 10
s1=A<0;
s2=A>=0;
J = 100*((s2.*A)./AW).^(c*z)+999*s1;

%step 11
Q=s2.*( (4/c)*( (J/100).^0.5 ).*(AW+4)*FL^0.25 ) + 999*s1;

%step 12
td=RGBA1(1,:)+RGBA1(2,:)+RGBA1(3,:)*(21/20);
s3=td<=0;
s4=td>0;
InfSucFail=(s1+s3)<0.5;
t=s4.* ( ( e.*( a.^2+b.^2 ).^0.5 )./(s4.*td +s3)  )+s3*999;
C=s4.* ( (t.^0.9).*( (J/100).^0.5)*(1.64-0.29^n)^0.73 ) + s3*999;
M=s4.* ( C*FL^0.25 ) + s3*999;
s1=Q==0;
s2=Q>0;
s=s2.* (100*(M./(Q+s1)).^0.5) + 0*s1;

end


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% compute RGBa' named RGBA1 for the forward model in step 6
function RGBA1=CAM02RGBA1M(RGB,FL)
temp=FL*RGB/100;
temp2=(abs(temp)).^0.42;
temp3=27.13+temp2;
temp4=(400*temp2)./temp3;
s1=temp>=0;
s2=temp<0;
RGBA1=(s1.*temp4)-s2.*temp4 +0.1;
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% hue angle calculation for given a and b:  a  horizontal axis, and b the vertical axis
% a and b can be vector. In this case, h is also a vector.
% if a and b are row vector, then h is row vector, and a and b are column
% vectors, then h is column vector too.
%
function h=HueAngle(a,b)
h=atan2(b,a)*180/pi;
s1=h<0;
s2=h>=0;
h1=(h+360).*s1;
h2=h.*s2;
h=h1+h2;
end

%%%%%%%%%%%%%%%%%%%%%%%%%%

function [XYZ,XYZw]=spd2xyz(spddata, obs, AorR,rfldata)
%Calculate XYZ from source spectrum (and reflectance spectrum)
%spddata = filename or matrixname of SPD data
%obs = 2 for 2 degree, 10 for 10 degree CIE standard observer
%AorR: absolute (1) or relative tristimulus values (default = 1), 
%rfldata = filename or matrixname of Reflectance data (0: calculate XYZ of SPD, not SPD.*RFL)
%
% author:    © K. Smet
% version: 1.1
% date: May 15, 2013, correction to wavelengthstep (for irregular spacing): March 15, 2014
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if nargin<2;obs=2;AorR=1;rfldata=0;;end
if nargin<3;AorR=1;rfldata=0;end
if nargin<4;rfldata=0;end

%read colour matching functions
[cmf,k]=selectcmf(obs);

%if data is file then read file else data is matlab matrix
if ischar(spddata) == 1  
    spd=convertspdformat(spddata);
    spd = dlmread(spddata);
else
    spd = spddata;
end

spd=spd(spd(:,1)>=359 & spd(:,1)<=831,:);

lambdas=spd(:,1);

%create delta_wavelength vector for use in summation-integral
d=diff(lambdas);
d1=[d(1);d(1:end-1)./2;d(end)];
d2=[0;d(2:end)./2;0];
dl=(d1+d2);

spd=spd(:,2);


%to save calculation time only perform interpolation when necessary
if abs(dl(1)-dl(2))==abs(mean(dl)) & (((dl(1)==5) | (dl(1)==1) | (dl(1)==2)) & ((lambdas(1,1)==380) | (lambdas(1,1)==360)) & ((lambdas(end,1)==780) | (lambdas(end,1)==830)));
%if (((dl(1)==5) | (dl(1)==1) | (dl(1)==2)) & ((lambdas(1,1)==380) | (lambdas(1,1)==360)) & ((lambdas(end,1)==780) | (lambdas(end,1)==830)));
    cmf=cmf(1:dl(1):end,2:end);
    if lambdas(1,1)==380;cmf=cmf(20/dl(1)+1:end-50/dl(1),:);end;%for 380:780 nm data
else
    for i=1:3;cmf_(:,i)=interpK(cmf(:,1),cmf(:,i+1),lambdas,'linear');end;cmf=cmf_;clear cmf_;
end
    

%Relative or absolute tristimulus values?
if AorR==0
        k=100./sum(spd.*cmf(:,2).*dl); %relative tristimulus
end

%surface color or object color? 
if rfldata(1,1)~=0 %=surface color
    %if data is file then read file else data is matlab matrix
    if ischar(rfldata) == 1  
        rfl=convertspdformat(rfldata);
        rfl = dlmread(rfldata);
    else
        rfl = rfldata;
    end

    for i=1:size(rfl,2)-1;
        rfl_(:,i)=interpK(rfl(:,1),rfl(:,i+1),lambdas,'linear'); 
    end
    rfl=rfl_;
    
    k=100./sum(spd.*cmf(:,2).*dl);
else %=selfluminous color
    rfl=ones(1,size(spd,1))'  ;
end

XYZ=nan(size(rfl,2),3);
for i=1:size(rfl,2);
    XYZ(i,:)=k*[sum(spd.*rfl(:,i).*cmf(:,1).*dl),sum(spd.*rfl(:,i).*cmf(:,2).*dl),sum(spd.*rfl(:,i).*cmf(:,3).*dl)];
end
XYZw=k*[sum(spd.*cmf(:,1).*dl),sum(spd.*cmf(:,2).*dl),sum(spd.*cmf(:,3).*dl)];

end


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function X=neg2zero(X)
X=(X+X.*sign(X))/2;
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function Ynew=interpK(X,Y,Xnew,type,extrap);
% 1-D interpolation (table lookup) with all negative values set to 0!
% Extrapolate if necessary: if extrapolation produces impossible results,
% set to closest old value.
%
%     YI = INTERP1(X,Y,XI) interpolates to find YI, the values of
%     the underlying function Y at the points in the vector, or array XI. X
%     must be a vector of length N, and SIZE(Y,1) must be N.  If Y is an array
%     of size [N,M1,M2,...,Mk] then the interpolation is performed for 
%     each M1-by-M2-by-...-Mk value in Y.  If XI is an array of size
%     [D1,D2,...,Dj], then YI will be of size [D1,D2,...,Dj,M1,M2,...,Mk].
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if nargin<5;extrap=1;end
if nargin <4; extrap=1;type='v5cubic';end
switch type
    case 'none'
    case 'lagrange'
        Ynew=Lagrange(X,Y,Xnew);
    case 'sprague';
        Ynew=sprague(X,Y,Xnew);
        if isnan(Ynew);Ynew = (interp1(X,Y,Xnew,'v5cubic'));end
    otherwise
        Ynew = (interp1(X,Y,Xnew,type));
        %plot(X,Y,'b-');hold on;plot(Xnew,Ynew,'b.-')
end
%extrapolate beyond begin and end boundary;
switch extrap
    case 0
        if sum(Ynew(Xnew<X(1))>0) | sum(isnan(Ynew(Xnew<X(1)))); Ynew(Xnew<X(1))=0;end %if extrapolation produces impossible results, set to closest old value.
        if sum(Ynew(Xnew>X(end))>0) | sum(isnan(Ynew(Xnew>X(end))));Ynew(Xnew>X(end))=0;end %if extrapolation produces impossible results, set to closest old value.
    case 1
        if sum(Ynew(Xnew<X(1))>0) | sum(isnan(Ynew(Xnew<X(1)))); Ynew(Xnew<X(1))=Y(1);end %if extrapolation produces impossible results, set to closest old value.
        if sum(Ynew(Xnew>X(end))>0) | sum(isnan(Ynew(Xnew>X(end))));Ynew(Xnew>X(end))=Y(end);end %if extrapolation produces impossible results, set to closest old value.
        
end


Ynew=neg2zero(Ynew);

end

