function data=convertspdformat(filename)
%convert komma decimal numbers to point decimal numbers
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
datastring=textread(filename,'%s');
chardatastring=char(datastring);
kommapos=find(chardatastring==',');
chardatastring(kommapos)='.';
data=str2double(cellstr(chardatastring));
lendata=length(data);
positions=(1:lendata);
oddn=find(mod(positions,2)~=0);
evenn=find(mod(positions,2)==0);
lamb=data(oddn);
spdy=data(evenn);
data=[lamb,spdy];
format long
dlmwrite(filename,data,'delimiter','\t','precision','%.12g');
end

function [DSPD,duv] = daylightSPD(T,lb,le,stepsize);
%calculates a CIE daylight phase based on
%T: CCT or CIE xy coordinates or xyz 
%lb=start wavelength 
%le=end wavelength 
%stepsize= wavelength interval
%if CCT <= 4000K a Planckian radiator is calculated instead 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if nargin==1;
    lambda =(360:1:830)';
else;
    if nargin<4;stepsize=1;end
    if nargin>=3;lambda=(lb:stepsize:le)';end
    if nargin==2 & numel(lb)>1;lambda=lb;else;lambda =(360:1:830)';end
end
lb=lambda(1);le=lambda(end);stepsize=abs(lambda(1)-lambda(2));

duv=[];
switch size(T,2)
    case 2;%input = CIExy
        [T,duv]=CCTa(xyY2xyz(T));
        if abs(duv)>5.4e-3;disp('Warning: duv too large!');end
    case 3;%input=XYZ
        [T,duv]=CCTa(T);    
        if abs(duv)>5.4e-3;disp('Warning: duv too large!');end
end
if T<4000;disp('Warning: CCT < 4000 K --> Planckian radiator!');end
        
