        else
            for i=1:3;St_interpolated(:,i)=(interp1(nm,St(:,i),lambda,'linear'));end;
            St=St_interpolated;
        end
    else
        for i=1:3;St_interpolated(:,i)=(interp1(nm,St(:,i),lambda,'linear'));end;
        St=St_interpolated;
    end
        
    if 4000<T<7000 
        xD=-4.607*(10^9/T^3)+2.9678*(10^6/T^2)+0.09911*(1000/T)+0.244063;
    else
        if T>7000
            xD=-2.0064*(10^9/T^3)+1.9018*(10^6/T^2)+0.24748*(1000/T)+0.23704; 
        end
    end      
    yD=-3*xD^2+2.87*xD-0.275;
    M1=(-1.3515-1.7703*xD+5.9114*yD)/(0.0241+0.2562*xD-0.7341*yD);
    M2=(0.03-31.4424*xD+30.0717*yD)/(0.0241+0.2562*xD-0.7341*yD);
    Sr=St(:,1)+M1*St(:,2)+M2*St(:,3);
    DSPD = [lambda,Sr./(sum(Sr).*abs(lambda(1)-lambda(2)))];
    DSPD(isnan(DSPD(:,2)),2)=0;
else
    DSPD=blackbodySPD(T,lb,le,stepsize);  
end

end


function [Sr,duv] = blackbodySPD(T, lb,le,stepsize);
%calculates black body radiator spectrum based on
%T= T or CIE xy coordinates or xyz 
%lb=start wavelength 
%le=end wavelength 
%stepsize= wavelength interval
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
if nargin==1;
    lambda =(360:1:830)';
else;
    if nargin<4;stepsize=1;end
    if nargin>=3;lambda=(lb:stepsize:le)';end
    if nargin==2 & numel(lb)>1;lambda=lb;else;lambda =(360:1:830)';end
end
lb=lambda(1);le=lambda(end);stepsize=abs(lambda(1)-lambda(2));



duv=[];
switch size(T,2)
    case 2;%input = CIExy
        [T,duv]=CCTa(xyY2xyz(T));
        if abs(duv)>5.4e-3;disp('Warning: duv too large!');end
    case 3;%input=XYZ
        [T,duv]=CCTa(T);    
        if abs(duv)>5.4e-3;disp('Warning: duv too large!');end
end
c1 = 3.74183e-16;
c2 =  1.4388*10^-2;
n=1.000;

Sr=(1/pi)*c1*((lambda.*1e-9).^(-5))*(n^(-2)).*(exp(c2*((n.*lambda.*1e-9.*T).^(-1)))-1).^(-1);
Sr560=(1/pi)*c1*((560*1e-9).^(-5))*(n^(-2)).*(exp(c2*((n*560*1e-9.*T).^(-1)))-1).^(-1);
Sr=Sr./Sr560;
Sr = [lambda,Sr];
end

function [cmf,k]=selectcmf(observer)
